import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"唐·库赫","description":"","frontmatter":{"title":"唐·库赫","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/唐·库赫.md","filePath":"04_people/唐·库赫.md"}'),n={name:"04_people/唐·库赫.md"};function l(i,e,s,_,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="唐·库赫-don-keough" tabindex="-1">唐·库赫（Don Keough） <a class="header-anchor" href="#唐·库赫-don-keough" aria-label="Permalink to &quot;唐·库赫（Don Keough）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：可口可乐公司前总裁（President）</li><li><strong>与巴菲特关系</strong>：可口可乐核心高管，与巴菲特私交深厚，是巴菲特的老朋友</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>唐·库赫是可口可乐公司历史上最具传奇色彩的高管之一。他在可口可乐任职长达数十年，从基层做起，一路晋升至公司总裁兼首席运营官，与CEO罗伯托·戈伊苏埃塔（Roberto Goizueta）形成了黄金搭档。库赫不仅是一位杰出的商业领袖，更以直言不讳、幽默风趣的个性著称，是可口可乐公司文化的灵魂人物之一。他深谙企业运营，对可口可乐的全球扩张战略有着不可替代的贡献。在戈伊苏埃塔任内推动可口可乐全球化的进程中，库赫作为运营操盘手，承担了大量关键工作。巴菲特与库赫的友谊是商业史上最经典的&quot;伯乐与良驹&quot;故事之一——巴菲特曾表示，库赫是他最欣赏的人之一。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1981年</strong>：戈伊苏埃塔出任可口可乐CEO，库赫作为核心副手共同推进改革</li><li><strong>1985年</strong>：可口可乐推出&quot;新可乐&quot;（New Coke），库赫在危机中发挥关键作用，最终推动公司回归经典配方</li><li><strong>1993年</strong>：库赫随戈伊苏埃塔一同受到巴菲特增持可口可乐的关注</li><li><strong>1997年</strong>：戈伊苏埃塔去世后，库赫继续以高级顾问身份为可口可乐服务</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p>',8)])])}const c=t(n,[["render",l]]);export{p as __pageData,c as default};
